using Bliss.Domain.Financials;
using Npgsql;
namespace Bliss.Infrastructure.Financials;
// No real provider dispatch. Quote authority must be revalidated by the mock application adapter.
public sealed class MockPaymentCaptureStore(NpgsqlDataSource data)
{
 public async Task<PreparedPaymentOperation> Operation(Guid operationId,CancellationToken ct=default)
 {
  await using var c=data.CreateCommand("SELECT o.id,q.id,q.merchant_id,q.module,q.campaign_id,q.recipient_account,q.amount_minor,q.currency,o.provider_key FROM financials.payment_operations o JOIN financials.authorized_quotes q ON q.id=o.quote_id WHERE o.id=@i");c.Parameters.AddWithValue("i",operationId);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new InvalidOperationException("Unknown funding operation.");return new(r.GetGuid(0),r.GetGuid(1),new(r.GetGuid(2),Enum.Parse<FinancialModule>(r.GetString(3)),r.GetGuid(4)),r.GetGuid(5),r.GetInt64(6),r.GetString(7),r.GetString(8));
 }
 public async Task<Guid> Capture(PreparedPaymentOperation operation,VerifiedSandboxPayment payment,Guid payerAccount,Guid recipientOwner,CancellationToken ct=default)
 {
  if(payerAccount==Guid.Empty||recipientOwner==Guid.Empty||payment.PaymentIntentId!="pi_mock_"+operation.Id.ToString("N")||payment.Currency!="USD"||payment.AmountMinor!=operation.AmountMinor)throw new ArgumentException("Mock capture must match trusted operation/accounts.");
  return await CaptureCore(operation,payment,payerAccount,recipientOwner,null,null,ct);
 }
 public async Task<Guid> CaptureBound(PreparedPaymentOperation operation,VerifiedSandboxPayment payment,Guid payerAccount,Guid recipientOwner,string profile,string fingerprint,CancellationToken ct=default)
 {
  if(payerAccount==Guid.Empty||recipientOwner==Guid.Empty||!payment.PaymentIntentId.StartsWith("pi_fixture_",StringComparison.Ordinal)||payment.Currency!="USD"||payment.AmountMinor!=operation.AmountMinor||string.IsNullOrWhiteSpace(profile)||profile.Length>64||profile.Any(x=>!char.IsAsciiLetterOrDigit(x)&&x!='-'&&x!='_')||fingerprint.Length!=64||fingerprint.Any(x=>!Uri.IsHexDigit(x))||string.IsNullOrWhiteSpace(payment.EventId)||!payment.EventId.StartsWith("evt_",StringComparison.Ordinal)||payment.EventId.Length>120||payment.EventId.Any(char.IsControl))throw new ArgumentException("Bound mock fixture/profile evidence required.");
  return await CaptureCore(operation,payment,payerAccount,recipientOwner,profile,fingerprint,ct);
 }
 private async Task<Guid> CaptureCore(PreparedPaymentOperation operation,VerifiedSandboxPayment payment,Guid payerAccount,Guid recipientOwner,string? profile,string? fingerprint,CancellationToken ct)
 {
  await using var c=await data.OpenConnectionAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
  await using(var locked=new NpgsqlCommand("SELECT q.id,q.merchant_id,q.module,q.campaign_id,q.recipient_account,q.amount_minor,q.currency,o.provider_key FROM financials.payment_operations o JOIN financials.authorized_quotes q ON q.id=o.quote_id WHERE o.id=@i FOR UPDATE OF o",c,tx)){locked.Parameters.AddWithValue("i",operation.Id);await using var reader=await locked.ExecuteReaderAsync(ct);if(!await reader.ReadAsync(ct)||reader.GetGuid(0)!=operation.QuoteId||reader.GetGuid(1)!=operation.Scope.MerchantId||reader.GetString(2)!=operation.Scope.Module.ToString()||reader.GetGuid(3)!=operation.Scope.CampaignId||reader.GetGuid(4)!=operation.RecipientAccountId||reader.GetInt64(5)!=operation.AmountMinor||reader.GetString(6)!=operation.Currency||reader.GetString(7)!=operation.ProviderKey)throw new InvalidOperationException("Capture does not match immutable funding operation.");}
  await using(var gate=new NpgsqlCommand("SELECT pg_advisory_xact_lock(hashtextextended(@key,0))",c,tx)){gate.Parameters.AddWithValue("key","stripe-sandbox:"+payment.EventId);await gate.ExecuteNonQueryAsync(ct);}
  Guid? priorJournal=null;
  await using(var prior=new NpgsqlCommand("SELECT journal_id,payment_intent_id FROM financials.payment_captures WHERE operation_id=@i",c,tx)){prior.Parameters.AddWithValue("i",operation.Id);await using var r=await prior.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct)){if(r.GetString(1)!=payment.PaymentIntentId)throw new InvalidOperationException("Funding operation already captured by another provider identity.");priorJournal=r.GetGuid(0);}}
  await using(var priorEvent=new NpgsqlCommand("SELECT operation_id,fingerprint,journal_id FROM financials.mock_provider_events WHERE event_id=@e",c,tx)){priorEvent.Parameters.AddWithValue("e",payment.EventId);await using var r=await priorEvent.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct)){if(profile is null||r.GetGuid(0)!=operation.Id||r.GetString(1)!=fingerprint||priorJournal!=r.GetGuid(2))throw new InvalidOperationException("Event replay conflicts with original mock attribution.");}}
  await using(var statusConflict=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM financials.mock_payment_status_events WHERE event_id=@e) OR (@uncaptured AND (EXISTS(SELECT 1 FROM financials.mock_payment_status_events WHERE operation_id=@i AND state='CANCELED') OR EXISTS(SELECT 1 FROM financials.mock_payment_recoveries WHERE operation_id=@i AND provider_status='canceled'))) OR EXISTS(SELECT 1 FROM financials.mock_payment_status_events WHERE operation_id=@i AND profile_id<>@profile) OR EXISTS(SELECT 1 FROM financials.mock_payment_recoveries WHERE operation_id=@i AND profile_id<>@profile)",c,tx)){statusConflict.Parameters.AddWithValue("e",payment.EventId);statusConflict.Parameters.AddWithValue("i",operation.Id);statusConflict.Parameters.AddWithValue("uncaptured",priorJournal is null);statusConflict.Parameters.AddWithValue("profile",NpgsqlTypes.NpgsqlDbType.Varchar,(object?)profile??DBNull.Value);if(await statusConflict.ExecuteScalarAsync(ct) is true)throw new InvalidOperationException("Status evidence conflicts or cancellation requires review.");}
  if(profile is not null)
  {
   await using(var bind=new NpgsqlCommand("INSERT INTO financials.mock_provider_bindings(operation_id,profile_id,payment_intent_id,payer_account,recipient_owner) SELECT @i,@profile,@pi,@payer,@owner WHERE (EXISTS(SELECT 1 FROM financials.payment_dispatch_results WHERE operation_id=@i AND state='BOUND' AND payment_intent_id=@pi) OR EXISTS(SELECT 1 FROM financials.mock_payment_recoveries WHERE operation_id=@i AND payment_intent_id=@pi AND profile_id=@profile)) ON CONFLICT DO NOTHING",c,tx)){bind.Parameters.AddWithValue("i",operation.Id);bind.Parameters.AddWithValue("profile",profile);bind.Parameters.AddWithValue("pi",payment.PaymentIntentId);bind.Parameters.AddWithValue("payer",payerAccount);bind.Parameters.AddWithValue("owner",recipientOwner);await bind.ExecuteNonQueryAsync(ct);}
   await using(var check=new NpgsqlCommand("SELECT profile_id,payment_intent_id,payer_account,recipient_owner FROM financials.mock_provider_bindings WHERE operation_id=@i",c,tx)){check.Parameters.AddWithValue("i",operation.Id);await using var r=await check.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct)||r.GetString(0)!=profile||r.GetString(1)!=payment.PaymentIntentId||r.GetGuid(2)!=payerAccount||r.GetGuid(3)!=recipientOwner)throw new InvalidOperationException("Mock provider binding conflicts with frozen authority.");}
   if(priorJournal is Guid existing)
   {
    // A second valid event for the same bound identity records evidence without a second receipt/journal.
    await using(var receipt=new NpgsqlCommand("SELECT payment_intent_id,journal_id FROM financials.stripe_receipts WHERE event_id=@e",c,tx)){receipt.Parameters.AddWithValue("e",payment.EventId);await using var r=await receipt.ExecuteReaderAsync(ct);if(await r.ReadAsync(ct) && (r.GetString(0)!=payment.PaymentIntentId||r.GetGuid(1)!=existing))throw new InvalidOperationException("Event already attributed to another capture.");}
    await RecordMockEvent(existing);await tx.CommitAsync(ct);return existing;
   }
  }
  // The caller receives an immutable store-loaded operation, and cannot supply recipients in the public DTO.
  var journal=new FinancialJournal(operation.Scope,"USD","capture-"+operation.Id.ToString("N"),"TEST_CAPTURE:"+operation.Id,[new(payerAccount,operation.Scope.MerchantId,"TEST_CASH",JournalSide.Debit,operation.AmountMinor),new(operation.RecipientAccountId,recipientOwner,"TEST_RECIPIENT",JournalSide.Credit,operation.AmountMinor)]);
  var id=await new PostgresJournalStore(data).AppendWithin(c,tx,journal,payment,ct);
  await using var record=new NpgsqlCommand("INSERT INTO financials.payment_captures(operation_id,journal_id,payment_intent_id) VALUES(@i,@j,@p) ON CONFLICT DO NOTHING",c,tx);record.Parameters.AddWithValue("i",operation.Id);record.Parameters.AddWithValue("j",id);record.Parameters.AddWithValue("p",payment.PaymentIntentId);await record.ExecuteNonQueryAsync(ct);if(profile is not null)await RecordMockEvent(id);await tx.CommitAsync(ct);return id;
  async Task RecordMockEvent(Guid journalId)
  {
   await using var insert=new NpgsqlCommand("INSERT INTO financials.mock_provider_events(event_id,operation_id,fingerprint,journal_id) VALUES(@e,@i,@f,@j) ON CONFLICT DO NOTHING",c,tx);insert.Parameters.AddWithValue("e",payment.EventId);insert.Parameters.AddWithValue("i",operation.Id);insert.Parameters.AddWithValue("f",fingerprint!);insert.Parameters.AddWithValue("j",journalId);await insert.ExecuteNonQueryAsync(ct);
  }
 }
 public async Task<string> BoundMockIntent(Guid operation,CancellationToken ct=default)
 {await using var c=data.CreateCommand("SELECT payment_intent_id FROM financials.payment_dispatch_results WHERE operation_id=@i AND state='BOUND' UNION SELECT payment_intent_id FROM financials.mock_payment_recoveries WHERE operation_id=@i");c.Parameters.AddWithValue("i",operation);var id=await c.ExecuteScalarAsync(ct) as string;if(id is null||!id.StartsWith("pi_fixture_",StringComparison.Ordinal))throw new InvalidOperationException("Persisted intercepted mock dispatch identity required.");return id;}
 public async Task<string> CapturedPaymentIntent(Guid operation,CancellationToken ct=default)
 {await using var c=data.CreateCommand("SELECT payment_intent_id FROM financials.payment_captures WHERE operation_id=@i");c.Parameters.AddWithValue("i",operation);return await c.ExecuteScalarAsync(ct) as string ?? throw new InvalidOperationException("No simulated capture for funding operation.");}
 public async Task<Guid?> Captured(Guid operation,CancellationToken ct=default){await using var c=data.CreateCommand("SELECT journal_id FROM financials.payment_captures WHERE operation_id=@i");c.Parameters.AddWithValue("i",operation);return await c.ExecuteScalarAsync(ct) is Guid id?id:null;}
 public async Task<Guid> OperationForRefund(Guid refund,CancellationToken ct=default){await using var c=data.CreateCommand("SELECT c.operation_id FROM financials.refund_requests r JOIN financials.payment_captures c ON c.payment_intent_id=r.payment_intent_id WHERE r.id=@i");c.Parameters.AddWithValue("i",refund);return await c.ExecuteScalarAsync(ct) is Guid id?id:throw new InvalidOperationException("Unknown mock refund.");}
 public async Task<PreparedPaymentOperation[]> Owned(string subject,FinancialModule module,CancellationToken ct=default)
 {await using var c=data.CreateCommand("SELECT o.id FROM financials.payment_operations o JOIN financials.authorized_quotes q ON q.id=o.quote_id WHERE q.advertiser_subject=@s AND q.module=@m ORDER BY o.recorded_at LIMIT 100");c.Parameters.AddWithValue("s",subject);c.Parameters.AddWithValue("m",module.ToString());var ids=new List<Guid>();await using(var r=await c.ExecuteReaderAsync(ct)){while(await r.ReadAsync(ct))ids.Add(r.GetGuid(0));}var result=new List<PreparedPaymentOperation>();foreach(var id in ids)result.Add(await Operation(id,ct));return result.ToArray();}
}
